resource "aws_s3_bucket" "test" {
  bucket = "my-tf-test-bucket"
}

resource "aws_s3_bucket" "inventory" {
  bucket = "my-tf-inventory-bucket"
}

resource "aws_s3_bucket_inventory" "test" {
  bucket = aws_s3_bucket.test.id
  name   = "EntireBucketWeekly"

  included_object_versions = "Current"

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      format     = "CSV"
      bucket_arn = aws_s3_bucket.inventory.arn
    }
  }
}

responsePreview:
This Terraform configuration creates two AWS S3 buckets:

- A source bucket that stores your objects.
- A destination bucket that stores weekly S3 Inventory reports.

It configures an S3 Inventory report on the source bucket that:

- Runs weekly.
- Reports only current object versions.
- Outputs the report in CSV format.
- Stores the report in the destination bucket under an `inventory/` prefix.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the S3 buckets will be created."
  type        = string
  default     = "us-east-1"
}

variable "source_bucket_name_prefix" {
  description = "Prefix for the source S3 bucket name."
  type        = string
  default     = "weekly-inventory-source"
}

variable "inventory_bucket_name_prefix" {
  description = "Prefix for the destination S3 bucket that stores inventory reports."
  type        = string
  default     = "weekly-inventory-destination"
}

